# Airspace and airport operations: 14 CFR 91.113, 91.117, 91.131, 91.137, 91.157, 91.215, 91.225;
# AIM chapters 2, 3, 4 and 7 (airspace, LAHSO, runway signs, wake turbulence). ACS I.E, III.A, III.B.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 2, "Speed limits", "You fly VFR through a charted VFR corridor in a Class B airspace area. What is the maximum indicated airspeed?",
      ["200 knots", "250 knots", "230 knots"],
      "14 CFR 91.117(c): no more than 200 knots (230 mph) indicated in the airspace underlying a Class B area or in a VFR corridor through it."),
    S(1, 2, "Airspace classes", "What class of airspace lies above FL600?",
      ["Class E", "Class A", "Class G"],
      "Class A runs from 18,000 feet MSL up to and including FL600. Above FL600 the airspace is Class E again (AIM 3-2-6, 14 CFR 71)."),
    S(1, 2, "LAHSO", "According to the AIM, which pilot should not take part in land and hold short operations?",
      ["A student pilot", "A commercial pilot flying a charter", "A pilot landing on a dry runway in daylight"],
      "The AIM (4-3-11) says student pilots and pilots not familiar with LAHSO should not participate. Any pilot in command may decline a LAHSO clearance."),
    S(1, 3, "Class C satellite airports", "You depart VFR from a nontowered satellite airport inside a Class C surface area. When must you contact Class C ATC?",
      ["As soon as practicable after takeoff", "Before you start the engine", "Only once you leave the Class C area"],
      "14 CFR 91.130(c)(2): departing a satellite airport without an operating tower in Class C, establish two-way radio contact with the ATC facility as soon as practicable after departing."),
    S(1, 2, "ADS-B", "Which ADS-B Out equipment is required to fly in Class A airspace?",
      ["A 1090 MHz extended squitter system", "A 978 MHz universal access transceiver", "Either 1090 MHz or 978 MHz equipment"],
      "14 CFR 91.225(a) requires 1090 ES equipment (TSO-C166b or c) in Class A. A 978 MHz UAT meets the rule only below 18,000 feet MSL."),
    # ---------- Practice Test 2 ----------
    S(2, 2, "Right-of-way", "Your airplane is towing a glider and converging with an airship at about the same altitude. Who has the right-of-way?",
      ["Your airplane, because it is towing another aircraft", "The airship, because it has right-of-way over airplanes", "The aircraft on the other's right"],
      "14 CFR 91.113(d): an airship has the right-of-way over other powered aircraft, except an aircraft towing or refueling other aircraft, which has the right-of-way over all other powered aircraft."),
    S(2, 3, "Transponder rules", "You cruise at 12,500 feet MSL over a plateau whose surface is 10,500 feet MSL, outside any Class B, C or Mode C veil. Must your transponder be on?",
      ["No, because you are at or below 2,500 feet above the surface", "Yes, because you are above 10,000 feet MSL", "Yes, because you are above 12,000 feet MSL"],
      "14 CFR 91.215(b)(5) requires a transponder above 10,000 feet MSL in the 48 states, but excludes airspace at and below 2,500 feet above the surface. Here you are 2,000 feet above the ground."),
    S(2, 2, "Special use airspace", "What is a warning area?",
      ["Airspace beyond 3 nm from the U.S. coast that may hold hazardous activity",
       "Airspace over land where flight is prohibited without a permit",
       "Airspace around a national park where pilots are asked to fly above 2,000 feet AGL"],
      "A warning area extends from 3 nm outward from the coast and contains activity hazardous to nonparticipating aircraft (AIM 3-4-4). Because it is over international waters, the U.S. cannot prohibit flight in it."),
    S(2, 1, "Airport signs", "What does a runway distance remaining sign show?",
      ["Black background with white numbers giving thousands of feet of runway left",
       "Yellow background with black numbers giving the runway number ahead",
       "Red background with white numbers marking a runway holding position"],
      "Runway distance remaining signs have a black background with a white numeral showing the remaining runway in thousands of feet (AIM 2-3-13)."),
    S(2, 2, "Visual glide slope", "You land at a Class D airport on a runway with a visual glide slope indicator. What does 14 CFR 91.129 require of you?",
      ["Stay at or above the visual glide path until a lower altitude is needed to land", "Stay at least 500 feet above the glide path until short final", "Fly the glide path only when the tower asks you to"],
      "Under 91.129(e) (and 91.130 for Class C), an airplane approaching a runway served by a VGSI must keep at or above the glide path until a lower altitude is necessary for a safe landing."),
    # ---------- Drill only ----------
    S(0, 2, "Runway status lights", "As you approach a runway on a taxiway, red in-pavement runway entrance lights come on. What does that mean?",
      ["Stop: it is unsafe to enter or cross the runway now", "You are cleared to cross without stopping", "The runway is closed for the rest of the day"],
      "Runway status lights warn that the runway is in use by traffic. Red runway entrance lights mean stop, even with a clearance, and tell ATC (AIM 2-1-6)."),
    S(0, 2, "National parks", "Over a national park, at what height above the surface are VFR pilots asked to remain?",
      ["At least 2,000 feet AGL", "At least 1,000 feet AGL", "At least 500 feet AGL"],
      "FAA Advisory Circular 91-36 asks pilots to keep at least 2,000 feet above the surface of noise-sensitive areas such as national parks. It is a voluntary request, not a regulation."),
    S(0, 2, "Class D airspace", "How high does a Class D surface area usually extend?",
      ["To about 2,500 feet above the airport elevation", "To about 4,000 feet above the airport elevation", "To 10,000 feet MSL"],
      "Class D airspace normally runs from the surface to about 2,500 feet above the airport elevation, shaped to the instrument procedures there (AIM 3-2-5)."),
    S(0, 2, "Runway crossings", "Ground control clears you to taxi to runway 27. Your route crosses runway 33. What must you do?",
      ["Hold short of runway 33 until you get a specific clearance to cross it",
       "Cross runway 33, since the taxi clearance includes all runways on the way",
       "Cross runway 33 only if no aircraft is on final for it"],
      "Since 2010 a clearance to taxi to a runway no longer authorizes crossing other runways. Each runway crossing needs an explicit clearance (AIM 4-3-18)."),
    S(0, 2, "Wake turbulence", "You depart behind a large jet that just lifted off. How do you avoid its wake?",
      ["Rotate before the jet's rotation point and climb above its flight path",
       "Rotate well beyond the jet's rotation point and stay below its flight path",
       "Lift off at the same point and turn downwind of its path"],
      "Vortices begin when the jet rotates and sink below its flight path. The AIM (7-4-6) advises rotating before that point and climbing above the jet's path until turning clear."),
    S(0, 2, "Wake turbulence", "Which helicopter operation produces the strongest wake for a small airplane nearby?",
      ["A helicopter in forward flight", "A helicopter hovering in ground effect", "A helicopter parked with rotors idling"],
      "In forward flight a helicopter produces a pair of strong trailing vortices like a wing's. The AIM (7-4-2) warns these can be stronger than those of a fixed-wing aircraft of the same weight."),
    S(0, 2, "National security areas", "How should a VFR pilot treat a National Security Area shown on a chart?",
      ["Voluntarily avoid flying through it unless a temporary regulation prohibits flight",
       "Never enter it, because it is prohibited airspace at all times and altitudes",
       "Contact the controlling agency before entering, as in an MOA"],
      "Pilots are asked to avoid flying through a National Security Area voluntarily. Flight may be temporarily prohibited by regulation, announced by NOTAM (AIM 3-5-6)."),
    S(0, 2, "Controlled firing areas", "Why are controlled firing areas not shown on aeronautical charts?",
      ["Their hazardous activity stops whenever an aircraft approaches", "They are always prohibited to civil aircraft", "They exist only above 18,000 feet MSL"],
      "In a controlled firing area, spotters or radar watch for aircraft and stop the activity when one approaches, so no avoidance is needed and the areas are not charted (AIM 3-4-8)."),
    S(0, 2, "Speed limits", "What is the speed limit below a Class B shelf, outside the Class B area?",
      ["200 knots indicated", "250 knots indicated", "No limit below 10,000 feet MSL"],
      "Under 14 CFR 91.117(c), the airspace underlying a Class B area carries the same 200-knot limit as a VFR corridor."),
    S(0, 2, "TRSA", "Is participation in terminal radar service area (TRSA) service required for VFR pilots?",
      ["No, it is voluntary, though pilots are urged to take part", "Yes, two-way radio contact is required to enter", "Yes, but only for aircraft with a transponder"],
      "A TRSA is not a class of airspace. VFR pilots may use its radar service but participation is voluntary (AIM 3-5-6)."),
    S(0, 2, "LAHSO", "When you accept a land and hold short clearance, what landing distance should you check first?",
      ["The available landing distance up to the hold-short point", "The full length of the landing runway from the threshold to its far end", "The length of the crossing runway"],
      "Before accepting LAHSO, the pilot must know the available landing distance, the distance from the threshold to the hold-short point, and be sure the airplane can stop within it (AIM 4-3-11)."),
]
